const { withXcodeProject } = require('expo/config-plugins');

// Preserve spaces in the script path generated by Expo's iOS template.
module.exports = function withQuotedIosBundleScript(config) {
  return withXcodeProject(config, (config) => {
    const phases = config.modResults.hash.project.objects.PBXShellScriptBuildPhase;
    for (const phase of Object.values(phases)) {
      if (typeof phase !== 'object' || !phase.name?.includes('Bundle React Native code and images')) {
        continue;
      }
      const script = JSON.parse(phase.shellScript);
      phase.shellScript = JSON.stringify(
        script.replace(/^(`[^\n]*react-native-xcode\.sh[^\n]*`)$/m, '"$1"'),
      );
    }
    return config;
  });
};
